-- Applied transactionally, first on the verification branch, then production.
CREATE SCHEMA ghostdesk;
CREATE TABLE ghostdesk.schema_migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ghostdesk.case_versions (
  version_id varchar(80) PRIMARY KEY,
  case_id varchar(80) NOT NULL,
  package jsonb NOT NULL,
  published boolean NOT NULL DEFAULT false,
  published_at timestamptz NOT NULL DEFAULT now(),
  CHECK (jsonb_typeof(package) = 'object'),
  CHECK (package->>'versionId' = version_id),
  CHECK (package->>'caseId' = case_id),
  CHECK (package->>'schemaVersion' = '1'),
  CHECK (package->>'engineVersion' = 'ghostdesk-core-1')
);
CREATE INDEX case_versions_public_idx ON ghostdesk.case_versions (published_at DESC, version_id) WHERE published = true;
INSERT INTO ghostdesk.case_versions(version_id, case_id, package, published)
VALUES ('demo-0317-v1', 'demo-0317', $case${"schemaVersion":1,"engineVersion":"ghostdesk-core-1","caseId":"demo-0317","versionId":"demo-0317-v1","title":"03:17에 멈춘 전송","description":"기록 담당자가 사라진 새벽. 남겨진 컴퓨터에는 외부 전송 기록 한 줄이 남아 있다. 기록을 대조해 그날의 일을 재구성하라.","estimatedMinutes":15,"contentWarning":"실종을 암시하는 허구의 이야기. 공포 이미지·점프 스케어 없음.","files":[{"id":"f-handover","type":"TEXT","title":"인수인계.txt","parentId":null,"visible":true,"clueId":"c-clock","text":"다음 근무자에게\n\n기록용 PC의 시계가 벽시계보다 7분 빠릅니다. 아직 보정하지 못했으니 전송 기록을 볼 때 주의하세요.\n\n보관함 암호는 마지막 전송 요청의 실제 시각입니다. HHMM 네 자리로 입력하세요. 새벽 3시 5분이라면 0305입니다.\n\n휴지통에 예전 큐 기록이 남아 있을 겁니다. 요청했다는 기록과 실제 완료 기록은 구분해서 확인해 주세요.\n\n— 기록 담당자, 윤서\n\n이 컴퓨터의 모든 파일과 대화는 가상의 사건 자료입니다. 실제 PC에는 영향을 주지 않습니다."},{"id":"f-chat","type":"CHAT_LINK","title":"메신저","parentId":null,"visible":true,"text":""},{"id":"f-photo","type":"IMAGE","title":"작업실_기록.img","parentId":null,"visible":true,"assetId":"clock-comparison","alt":"같은 순간을 기록한 작업실 자료. 벽시계는 03:10, PC 화면의 시계는 03:17을 가리킨다.","text":"야간 점검 담당자가 같은 순간에 기록한 두 시계.","clueId":"c-photo"},{"id":"f-vault","type":"FOLDER","title":"보관함","parentId":null,"visible":true,"puzzleId":"p-vault","text":""},{"id":"trash","type":"FOLDER","title":"휴지통","parentId":null,"visible":true,"text":"삭제된 기록도 흔적을 남깁니다."},{"id":"f-queue","type":"TEXT","title":"transfer_queue.log","parentId":"trash","visible":true,"clueId":"c-queue","text":"ARCHIVE NODE / OUTBOUND QUEUE\n──────────────────────────\n시각 기준: 기록용 PC\n\n[03:17:00] SEND_REQUEST\n요청 ID      : TX-0917\n목적지       : EXTERNAL_ARCHIVE\n상태         : QUEUED\n완료 시각    : —\n\nQUEUED = 승인 대기열 등록\n전송 완료는 별도 영수증에서 확인합니다.\n──────────────────────────\n이 로그는 요청 사실만 기록합니다."},{"id":"f-receipt","type":"TEXT","title":"전송_처리_영수증.txt","parentId":"f-vault","visible":false,"clueId":"c-receipt","text":"OUTBOUND TRANSFER RECEIPT\n──────────────────────────\n요청 ID      : TX-0917\n승인 처리    : CANCELLED\n최종 상태    : 전송 승인 취소\n전송 완료    : 0건\n외부 전송량  : 0 bytes\n\n승인이 취소되어 대기열의 요청은 실행되지 않았습니다.\n\n이 영수증의 요청 ID와 큐 로그의 요청 ID를 대조하세요."}],"clues":[{"id":"c-clock","title":"7분 빠른 PC 시계","description":"PC의 표시 시각에서 7분을 빼야 실제 시각이다."},{"id":"c-photo","title":"같은 순간, 다른 시각","description":"벽시계 03:10 / PC 화면 03:17."},{"id":"c-queue","title":"전송 요청 로그","description":"TX-0917은 03:17에 대기열에 등록됐다. 완료 기록은 없다."},{"id":"c-receipt","title":"승인 취소 영수증","description":"TX-0917 승인 취소. 전송 완료 0건, 전송량 0 bytes."}],"puzzles":[{"id":"p-vault","title":"보관함 암호","answer":"0310","ignoreCase":false,"hints":["인수인계 메모와 휴지통의 전송 기록을 살펴보세요.","큐 로그의 시각은 PC 시각입니다. 작업실 기록과 비교해 보세요.","PC는 7분 빠릅니다. 표시된 03:17에서 7분을 빼고 네 자리로 입력하세요.","정답은 0310입니다."]}],"messages":[{"id":"m-1","author":"민재","time":"03:24","text":"아직 연구실이야? 기록 담당자에게 연락이 안 돼.","initial":true},{"id":"m-2","author":"민재","time":"03:25","text":"난 03:10에는 이미 밖에 있었어. 근데 컴퓨터에 전송 기록이 남아 있다며?","initial":true},{"id":"m-3","author":"민재","time":"03:27","text":"혹시 그거 실제로 전송된 게 맞아? 대기열에 들어간 것과 완료된 건 다를 수 있어.","initial":false},{"id":"m-4","author":"민재","time":"03:28","text":"보관함이 열렸구나. 영수증의 요청 번호도 꼭 확인해 줘.","initial":false}],"rules":[{"id":"r-receipt","priority":10,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"p-vault"},"then":[{"type":"REVEAL_FILE","id":"f-receipt"},{"type":"APPEND_MESSAGE","id":"m-4"}]},{"id":"r-log-timer","priority":20,"once":true,"when":{"type":"FILE_READ","id":"f-queue"},"then":[{"type":"START_TIMER","id":"t-reply","durationMs":2500}]},{"id":"r-followup","priority":30,"once":true,"when":{"type":"TIMER_REACHED","id":"t-reply"},"then":[{"type":"APPEND_MESSAGE","id":"m-3"}]}],"endings":[{"id":"ending-a","title":"전송은 완료되지 않았다","text":"03:17은 7분 빠른 PC에 남은 요청 시각이었다. 실제 시각은 03:10.\n\n같은 요청 번호의 영수증은 승인이 취소되었고 외부 전송이 0건이었다는 사실을 보여준다. 전송을 요청한 흔적은 있었지만, 자료는 밖으로 나가지 않았다.\n\n민재의 발언만으로 누군가를 범인이라 단정할 수는 없다. 당신은 추측 대신 기록으로 결론을 완성했다.","revisitable":false},{"id":"ending-b","title":"기록보다 앞선 의심","text":"민재가 자리를 떠났다는 말과 PC의 시각만으로 자료 유출을 단정했습니다. 하지만 시계의 오차와 실제 전송 결과가 확인되지 않았습니다.\n\n이 결론에는 근거가 부족합니다. 조사로 돌아가 요청 로그와 처리 영수증을 대조하세요.","revisitable":true}],"hypotheses":[{"id":"h-no-transfer","label":"전송은 요청됐지만 완료되지 않았다.","endingId":"ending-a","requiredClues":["c-queue","c-receipt"]},{"id":"h-accuse","label":"민재가 자료를 외부로 전송했다.","endingId":"ending-b","requiredClues":[]}]}$case$::jsonb, true);
INSERT INTO ghostdesk.schema_migrations(version) VALUES (1);
